import { migrate } from "drizzle-orm/expo-sqlite/migrator";
import { db } from "./index";


// @ts-ignore generated by `drizzle-kit generate`
import migrations from "../drizzle/migrations"; // adjust the path if `src` is not at the project root

let running: Promise<void> | null = null;

/** Same name as before, so AuthBootstrap keeps working. Safe to call several times. */
export function runMigrations(): Promise<void> {
    running ??= migrate(db, migrations).finally(() => {
        running = null;
    });
    return running;
}